INSERT INTO public.novels ("id", "author_uid", "author_name", "author_photo", "title", "genre", "summary", "cover_image", "status", "likes_count", "views_count", "shares_count", "language", "violence_level", "moral_tone", "font_family", "font_size", "text_align", "line_height", "previous_part_id", "terabox_link", "created_at", "updated_at") VALUES ('n_001', 'user_master_01', 'أحمد محمود', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150', 'ظل العرش المفقود', 'fantasy', 'ملحمة أدبية تحكي عن صراع الممالك القديمة والبحث عن التاج المفقود في أرض الأسرار والغموض، حيث يتصدى الفارس أدهم للقوى المظلمة لحماية عقيدته وشعبه.', 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?q=80&w=800', 'published', 142, 2890, 35, 'ar', 'moderate', 'heroic', 'var(--font-serif)', '1.125rem', 'right', '1.75', NULL, '', '"2026-08-08T15:28:11.319Z"'::jsonb, '"2026-08-08T15:28:11.319Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.novels ("id", "author_uid", "author_name", "author_photo", "title", "genre", "summary", "cover_image", "status", "likes_count", "views_count", "shares_count", "language", "violence_level", "moral_tone", "font_family", "font_size", "text_align", "line_height", "previous_part_id", "terabox_link", "created_at", "updated_at") VALUES ('n_003', 'user_layla_04', 'ليلى العمري', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?w=150', 'صدى الكلمات والإلهام', 'drama', 'قصة إنسانية عميقة تتناول دراما العلاقات، التضحية، والبحث عن الذات عبر مختلف مراحل الحياة والتحديات الروحية.', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?q=80&w=800', 'published', 215, 4120, 68, 'ar', 'none', 'inspirational', 'var(--font-serif)', '1.125rem', 'right', '1.75', NULL, '', '"2026-08-08T15:28:11.319Z"'::jsonb, '"2026-08-08T15:28:11.319Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.novels ("id", "author_uid", "author_name", "author_photo", "title", "genre", "summary", "cover_image", "status", "likes_count", "views_count", "shares_count", "language", "violence_level", "moral_tone", "font_family", "font_size", "text_align", "line_height", "previous_part_id", "terabox_link", "created_at", "updated_at") VALUES ('n_004', 'user_master_01', 'أحمد محمود', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150', 'أرباب الأفق الأخبر', 'sci-fi', 'رحلة مستقبليّة عبر أبعاد الكون المظلم للبحث عن ملاذ جديد للبشرية بعد تحول مناخ الأرض واكتشاف مجرة غير مطروقة.', 'https://images.unsplash.com/photo-1506703719100-a0f3a48c0f86?q=80&w=800', 'published', 76, 1100, 12, 'ar', 'moderate', 'sci-fi', 'var(--font-serif)', '1.125rem', 'right', '1.75', NULL, '', '"2026-08-08T15:28:11.319Z"'::jsonb, '"2026-08-08T15:28:11.319Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.novels ("id", "author_uid", "author_name", "author_photo", "title", "genre", "summary", "cover_image", "status", "likes_count", "views_count", "shares_count", "language", "violence_level", "moral_tone", "font_family", "font_size", "text_align", "line_height", "previous_part_id", "terabox_link", "created_at", "updated_at") VALUES ('n_002', 'user_sara_02', 'سارة النجار', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=150', 'سر السراديب المعتمة', 'mystery', 'تحقيق غامض في مدينة أندلسية قديمة يكشف عن شبكة من الأسرار والرموز التاريخية المخبأة منذ قرون خلف الجدران العتيقة.', 'https://images.unsplash.com/photo-1532012197267-da84d127e765?q=80&w=800', 'published', 98, 1751, 21, 'ar', 'none', 'suspense', 'var(--font-serif)', '1.125rem', 'right', '1.75', NULL, '', '"2026-08-08T15:28:11.319Z"'::jsonb, '"2026-08-08T15:28:11.319Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.chapters ("id", "novel_id", "title", "content", "description", "order", "created_at", "updated_at") VALUES ('c_001', 'n_001', 'الفصل الأول: البداية في أطلال الرماد', 'كانت الرياح تعصف بشدة فوق أسوار قلعة الضباب العتيقة. جلس أدهم فوق الصخرة العالية يرقب أفق المدينة الممتد تحت ضوء القمر الفضي. لم يكن القتال مجرد خيار بالنسبة له، بل كان واجباً محتوماً لقومه الذين انتظروا العودة لسنوات طويلة. وقف وبيده سيفه المحفور عليه الرموز القديمة، جاهزاً لمواجهة أخطار الغد.', 'بداية رحلة أدهم وحكايته في القلعة العتيقة.', 1, '"2026-08-08T15:28:11.322Z"'::jsonb, '"2026-08-08T15:28:11.322Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.chapters ("id", "novel_id", "title", "content", "description", "order", "created_at", "updated_at") VALUES ('c_002', 'n_001', 'الفصل الثاني: همس الرياح الساطعة', 'دخل أدهم إلى الممر المظلم أسفل القلعة، حيث تفوح رائحة القدم والأسرار. سرعان ما سمع صوتاً خافتاً يناديه باسمه القديم. التفت يميناً فرأى نقشاً مضيئاً على الجدار يرمز للعرش المفقود...', 'استكشاف السراديب واكتشاف الخريطة المخفية.', 2, '"2026-08-08T15:28:11.322Z"'::jsonb, '"2026-08-08T15:28:11.322Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.chapters ("id", "novel_id", "title", "content", "description", "order", "created_at", "updated_at") VALUES ('c_003', 'n_001', 'الفصل الثالث: الفارس والأحجار السبعة', 'بدأت الرحلة الحقيقية نحو وادي الأسرار. جمع أدهم رفاقه السبعة في الفجر للبدء في البحث عن الأحجار السحرية.', 'تجميع الرفاق وتحديد الخطة الأولى.', 3, '"2026-08-08T15:28:11.322Z"'::jsonb, '"2026-08-08T15:28:11.322Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.chapters ("id", "novel_id", "title", "content", "description", "order", "created_at", "updated_at") VALUES ('c_004', 'n_002', 'الفصل الأول: جريمة في القصر الأثري', 'في ليلة ممطرة، تسلل المفتش فريد إلى مكتبة القصر الأندلسي بعد تلقيه بلاغاً غامضاً عن اختفاء المخطوطة النادرة. وجد الباب مفتوحاً والأوراق مبعثرة على الأرض بشكل يثير الريبة.', 'بداية التحقيق الغامض واكتشاف المخطوطة المفقودة.', 1, '"2026-08-08T15:28:11.322Z"'::jsonb, '"2026-08-08T15:28:11.322Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.chapters ("id", "novel_id", "title", "content", "description", "order", "created_at", "updated_at") VALUES ('c_005', 'n_002', 'الفصل الثاني: الرسالة المجهولة', 'عثر فريد بين طيات الكتب على مغلف أسود مغلق بالشمع الأحمر، مكتوب عليه عبارة واحدة باللغة القديمة.', 'تحليل الرسالة وتتبع الخيوط الأولى.', 2, '"2026-08-08T15:28:11.322Z"'::jsonb, '"2026-08-08T15:28:11.322Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.chapters ("id", "novel_id", "title", "content", "description", "order", "created_at", "updated_at") VALUES ('c_006', 'n_003', 'الفصل الأول: رحيل ناعم', 'في زاوية ذلك المقهى الهادئ، جلست مريم تسجل خاطراتها في مفكرتها الصغيرة. لم تكن تعلم أن هذا اليوم سيغير مجرى حياتها بالكامل.', 'لقاء مريم الأول وبداية التغير الكبير.', 1, '"2026-08-08T15:28:11.322Z"'::jsonb, '"2026-08-08T15:28:11.322Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.chapters ("id", "novel_id", "title", "content", "description", "order", "created_at", "updated_at") VALUES ('c_007', 'n_004', 'الفصل الأول: الإشارة الأولى من المجرة', 'تلقت المحطة الفضائية الرئيسية إشارة تردد غريبة قادمة من النظام الشمسي المجاور. قرر القائد طارق تجهيز المركبة للرحلة الاستكشافية.', 'انطلاق المركبة الفضائية الاستكشافية.', 1, '"2026-08-08T15:28:11.322Z"'::jsonb, '"2026-08-08T15:28:11.322Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.characters ("id", "novel_id", "name", "role", "traits", "description", "created_at") VALUES ('char_01', 'n_001', 'الفارس أدهم', 'main', 'شجاع، نبيـل، حكيم', 'البطل الرئيسي، فارس مقدام يسعى لإعادة العرش والحفاظ على سلامة قومه.', '"2026-08-08T15:28:11.324Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.characters ("id", "novel_id", "name", "role", "traits", "description", "created_at") VALUES ('char_02', 'n_001', 'الحكيم إدريس', 'supporting', 'غريب الأطوار، خبير بالرموز', 'مرشد أدهم في رحلته ومكتشف الخرائط القديمة.', '"2026-08-08T15:28:11.324Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.characters ("id", "novel_id", "name", "role", "traits", "description", "created_at") VALUES ('char_03', 'n_002', 'المُحقق فريد', 'main', 'ذكي، دقيق الملاحظة', 'مفتش خبير في القضايا التاريخية والألغاز المعقدة.', '"2026-08-08T15:28:11.324Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.world_notes ("id", "novel_id", "title", "category", "content", "created_at") VALUES ('wn_01', 'n_001', 'خريطة الممالك السبع', 'geography', 'تتكون الأرض القديمة من سبع ممالك تحيط بالبحيرة الفضية، وتحدها القلاع المنيعة من الشمال.', '"2026-08-08T15:28:11.326Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.world_notes ("id", "novel_id", "title", "category", "content", "created_at") VALUES ('wn_02', 'n_001', 'نظام السحر والأحجار', 'magic', 'يعتمد السحر على سبعة أحجار كريمة متوازنة يمثل كل حجر منها عنصراً من عناصر الطبيعة.', '"2026-08-08T15:28:11.326Z"'::jsonb) ON CONFLICT DO NOTHING;
